// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public { c = new MyContract(); }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount <= address(this).balance);
        Reverter r = new Reverter();
        vm.deal(address(this), amount);
        vm.prank(address(this));
        bool ok;
        try c.sendTo(address(r), amount) { ok = true; } catch { ok = false; }
        assertTrue(!ok, "sendTo must revert when receiver rejects ETH");
    }
}

contract Reverter {
    fallback() external payable { revert(); }
}
